import type { IsoTimestamp, OrgId, ProjectId, UserId } from "./common";
import type { IssuePriority } from "./issue";

/** How often a recurring issue rule files a new issue. */
export type RecurrenceCadence = "daily" | "weekly";

/**
 * A rule that a background job turns into an ordinary issue.
 *
 * `startsOn`, `lastOccurrenceOn` and each occurrence day are `YYYY-MM-DD`
 * calendar dates. `weekday` is the ISO weekday, 1 = Monday … 7 = Sunday,
 * and is set only when `cadence` is `"weekly"`.
 */
export interface RecurringIssue {
  id: string;
  orgId: OrgId;
  projectId: ProjectId;
  title: string;
  priority: IssuePriority;
  assigneeId: UserId | null;
  cadence: RecurrenceCadence;
  weekday: number | null;
  timezone: string;
  startsOn: string;
  lastOccurrenceOn: string | null;
  paused: boolean;
  createdBy: UserId;
  createdAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
}

import { z } from "zod";
import { issuePrioritySchema } from "./issue";
import { orgIdSchema, projectIdSchema, userIdSchema } from "./common";

/**
 * Create-recurring-issue payload. Shared by the service and any future form.
 * Kept free of server-only imports, like every other schema in this folder.
 */

const CALENDAR_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** True when `value` is a real civil date, so `2026-02-30` is rejected. */
function isRealCalendarDate(value: string): boolean {
  if (!CALENDAR_DATE.test(value)) return false;
  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** True when this runtime's ICU data recognizes `value` as a time zone. */
function isKnownTimeZone(value: string): boolean {
  try {
    Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

const calendarDateSchema = z
  .string()
  .regex(CALENDAR_DATE, "must be a YYYY-MM-DD date")
  .refine(isRealCalendarDate, "must be a real calendar date");

const ianaTimeZoneSchema = z
  .string()
  .min(1)
  .refine(isKnownTimeZone, "must be an IANA time zone");

export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3).max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: z.enum(["daily", "weekly"]),
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: ianaTimeZoneSchema,
    startsOn: calendarDateSchema,
  })
  .refine((value) => value.cadence !== "weekly" || value.weekday !== null, {
    message: "A weekly rule needs a weekday",
    path: ["weekday"],
  })
  .refine((value) => value.cadence !== "daily" || value.weekday === null, {
    message: "A daily rule cannot set a weekday",
    path: ["weekday"],
  });

export type CreateRecurringIssueInput = z.input<typeof createRecurringIssueSchema>;

import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const recurringIssues = sqliteTable(
  "recurring_issues",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    title: text("title").notNull(),
    priority: text("priority", {
      enum: ["none", "low", "medium", "high", "urgent"],
    })
      .notNull()
      .default("none"),
    assigneeId: text("assignee_id"),
    cadence: text("cadence", { enum: ["daily", "weekly"] }).notNull(),
    /** ISO weekday, 1 = Monday … 7 = Sunday. Null on daily rules. */
    weekday: integer("weekday"),
    timezone: text("timezone").notNull(),
    startsOn: text("starts_on").notNull(),
    lastOccurrenceOn: text("last_occurrence_on"),
    paused: integer("paused", { mode: "boolean" }).notNull().default(false),
    createdBy: text("created_by").notNull(),
    ...timestampColumns,
  },
  (table) => [
    index("recurring_issues_org_created_idx").on(table.orgId, table.createdAt),
    index("recurring_issues_paused_idx").on(table.paused),
  ],
);

export type RecurringIssueRow = typeof recurringIssues.$inferSelect;
export type NewRecurringIssueRow = typeof recurringIssues.$inferInsert;

/**
 * Recurring-issue rules. Org-scoped reads go through `orgPredicate`; the job's
 * sweep is cross-tenant on purpose, the same way the webhook claim is.
 *
 * Must call (do not reimplement): orgPredicate
 */
import { and, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toRecurringIssue } from "./_mappers";
import type { OrgId, UserId } from "@/types/common";
import type { IssuePriority } from "@/types/issue";
import type { RecurrenceCadence, RecurringIssue } from "@/types/recurring-issue";

export interface NewRecurringIssue {
  readonly orgId: OrgId;
  readonly projectId: RecurringIssue["projectId"];
  readonly title: string;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
  readonly createdBy: UserId;
}

export async function insertRecurringIssue(
  input: NewRecurringIssue,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority,
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy: input.createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toRecurringIssue(row);
}

export async function findRecurringIssue(
  orgId: OrgId,
  id: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .get();
  return row ? toRecurringIssue(row) : null;
}

/** Every rule in the organization, oldest insert first. Paused rules included. */
export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(sql`rowid`)
    .all();
  return rows.map(toRecurringIssue);
}

/** Plan quota: every stored rule counts, paused ones included. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  id: string,
  paused: boolean,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${id} not found`);
  return toRecurringIssue(row);
}

export async function setLastOccurrenceOn(
  orgId: OrgId,
  id: string,
  lastOccurrenceOn: string,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ lastOccurrenceOn, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${id} not found`);
  return toRecurringIssue(row);
}

/**
 * Every non-paused rule, across organizations. The filing job is the only
 * caller; a request-scoped read must use `listRecurringIssues` instead.
 */
export async function listUnpausedRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(sql`rowid`)
    .all();
  return rows.map(toRecurringIssue);
}

/**
 * Recurring-issue rules: who may file them, which project they belong to, and
 * the plan cap on how many an organization may keep.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { projectResource, requireFound } from "./_support";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

/**
 * Stores a rule. Invalid input rejects with the schema's `ZodError` before
 * anything is written. The rule starts unpaused and with no occurrence filed.
 */
export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const parsed = createRecurringIssueSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(parsed.orgId, parsed.projectId),
    "Project",
    parsed.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (parsed.assigneeId !== null) {
    const assignee = await memberRepo.findMember(parsed.orgId, parsed.assigneeId);
    if (assignee === null || assignee.status !== "active") {
      throw new Error("Assignee is not an active member of the organization");
    }
  }

  const org = requireFound(
    await orgRepo.findOrgById(parsed.orgId),
    "Organization",
    parsed.orgId,
  );
  const used = await recurringRepo.countRecurringIssues(parsed.orgId);
  if (wouldExceedLimit(org.plan, "recurringIssues", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more recurring issues`,
    );
  }

  return recurringRepo.insertRecurringIssue({
    orgId: parsed.orgId,
    projectId: parsed.projectId,
    title: parsed.title,
    priority: parsed.priority,
    assigneeId: parsed.assigneeId,
    cadence: parsed.cadence,
    weekday: parsed.weekday,
    timezone: parsed.timezone,
    startsOn: parsed.startsOn,
    createdBy: actor.userId,
  });
}

/** Pause or resume one rule. Creating an issue in its project is the gate. */
export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringRepo.findRecurringIssue(input.orgId, input.recurringIssueId),
    "RecurringIssue",
    input.recurringIssueId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(rule.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  return recurringRepo.setRecurringIssuePaused(input.orgId, rule.id, input.paused);
}

/** Every rule in the actor's organization, in creation order. */
export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", { kind: "organization", orgId });
  return recurringRepo.listRecurringIssues(orgId);
}

/**
 * Files the latest due occurrence of every non-paused recurring-issue rule.
 *
 * Missed days are not back-filled: each rule produces at most one issue per
 * run, for the latest occurrence that has already started in the rule's zone.
 *
 * Must call (do not reimplement): createIssue
 */
import { createLogger } from "@/lib/logger";
import { can, PermissionDeniedError } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { projectResource } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/**
 * `processed` counts issues actually created. One rule's refusal or throw
 * never stops the sweep; a quota refusal leaves that rule exactly as it was.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listUnpausedRecurringIssues();

    for (const rule of rules) {
      try {
        await fileRule(rule, now, result);
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue rule failed", {
          id: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function fileRule(
  rule: RecurringIssue,
  now: Date,
  result: JobResult,
): Promise<void> {
  const latest = latestStartedOccurrence(rule, now);
  if (latest === null) return;
  if (rule.lastOccurrenceOn !== null && latest <= rule.lastOccurrenceOn) return;

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) {
    result.failed += 1;
    return;
  }
  if (isArchived(project)) return;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (creator === null || creator.status !== "active") {
    await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return;
  }

  const actor: Actor = {
    userId: creator.userId,
    orgId: rule.orgId,
    role: creator.role,
  };
  if (!can(actor, "issue:create", projectResource(project))) {
    await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return;
  }

  const assigneeId = await activeAssignee(rule);

  try {
    await createIssue(actor, {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${latest})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
      return;
    }
    result.failed += 1;
    logger.warn("recurring issue was not filed", {
      id: rule.id,
      reason: error instanceof Error ? error.message : String(error),
    });
    return;
  }

  await recurringRepo.setLastOccurrenceOn(rule.orgId, rule.id, latest);
  result.processed += 1;
}

/** The rule's assignee when they are still an active member; otherwise none. */
async function activeAssignee(rule: RecurringIssue): Promise<UserId | null> {
  if (rule.assigneeId === null) return null;
  const member = await memberRepo.findMember(rule.orgId, rule.assigneeId);
  if (member === null || member.status !== "active") return null;
  return rule.assigneeId;
}

/**
 * Latest occurrence day that has started by `now`.
 *
 * A day D starts at 00:00 in the rule's own time zone, daylight-saving
 * included — the civil date `Intl` reports for `now` is that day. Daily rules
 * occur every civil day on or after `startsOn`. Weekly rules occur on the
 * ISO weekday, and only on or after `startsOn`.
 */
function latestStartedOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = localCalendarDate(now, rule.timezone);
  if (today < rule.startsOn) return null;
  if (rule.cadence === "daily") return today;
  if (rule.weekday === null) return null;

  const delta = (isoWeekday(today) - rule.weekday + 7) % 7;
  const candidate = addCalendarDays(today, -delta);
  if (candidate < rule.startsOn) return null;
  return candidate;
}

/** Civil `YYYY-MM-DD` of `instant` in `timeZone`. */
function localCalendarDate(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);
  const year = parts.find((part) => part.type === "year")?.value ?? "";
  const month = parts.find((part) => part.type === "month")?.value ?? "";
  const day = parts.find((part) => part.type === "day")?.value ?? "";
  return `${year.padStart(4, "0")}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
}

/** ISO weekday of a civil date: 1 = Monday … 7 = Sunday. */
function isoWeekday(ymd: string): number {
  const year = Number(ymd.slice(0, 4));
  const month = Number(ymd.slice(5, 7));
  const day = Number(ymd.slice(8, 10));
  const jsDay = new Date(Date.UTC(year, month - 1, day)).getUTCDay();
  return jsDay === 0 ? 7 : jsDay;
}

function addCalendarDays(ymd: string, days: number): string {
  const year = Number(ymd.slice(0, 4));
  const month = Number(ymd.slice(5, 7));
  const day = Number(ymd.slice(8, 10));
  const date = new Date(Date.UTC(year, month - 1, day + days));
  const y = String(date.getUTCFullYear()).padStart(4, "0");
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

