import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { ZodError } from "zod";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
vi.mock("@/lib/id", () => import("./_support/doubles/id"));

import { getPlanLimits } from "@/config/plan-limits";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { getDb, members } from "@/server/db";
import { eq } from "drizzle-orm";
import { drain, enqueue } from "@/server/jobs";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import { CADENCE_MINUTES_TEST } from "@/server/jobs/scheduler";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueService from "@/server/services/recurring-issue-service";
import { toIsoTimestamp } from "@/types/common";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { OrgId, ProjectId, UserId } from "@/types/common";

let cleanup: () => void;
let growth: Tenant;
let starter: Tenant;
let free: Tenant;
let enterprise: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  growth = await createTenant("growthco", "growth");
  starter = await createTenant("startco", "starter");
  free = await createTenant("freeco", "free");
  enterprise = await createTenant("entco", "enterprise");
});

afterAll(() => {
  cleanup();
});

function input(
  tenant: Tenant,
  overrides: Record<string, unknown> = {},
) {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    title: "Daily triage",
    cadence: "daily" as const,
    timezone: "UTC",
    startsOn: "2026-03-01",
    ...overrides,
  };
}

describe("schema", () => {
  it("accepts a daily rule and defaults priority, assignee and weekday", () => {
    const parsed = createRecurringIssueSchema.parse(input(growth));
    expect(parsed.priority).toBe("none");
    expect(parsed.assigneeId).toBeNull();
    expect(parsed.weekday).toBeNull();
    expect(parsed.cadence).toBe("daily");
  });

  it("rejects weekly without weekday and daily with weekday", () => {
    expect(
      createRecurringIssueSchema.safeParse(input(growth, { cadence: "weekly" })).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse(
        input(growth, { cadence: "daily", weekday: 1 }),
      ).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse(
        input(growth, { cadence: "weekly", weekday: 1 }),
      ).success,
    ).toBe(true);
    expect(
      createRecurringIssueSchema.safeParse(
        input(growth, { cadence: "weekly", weekday: null }),
      ).success,
    ).toBe(false);
  });

  it("rejects impossible dates, bad zones and out-of-range weekdays", () => {
    expect(
      createRecurringIssueSchema.safeParse(input(growth, { startsOn: "2026-02-30" }))
        .success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse(input(growth, { startsOn: "2026-02-29" }))
        .success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse(input(growth, { startsOn: "2024-02-29" }))
        .success,
    ).toBe(true);
    expect(
      createRecurringIssueSchema.safeParse(input(growth, { timezone: "Not/AZone" }))
        .success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse(
        input(growth, { timezone: "America/New_York" }),
      ).success,
    ).toBe(true);
    expect(
      createRecurringIssueSchema.safeParse(
        input(growth, { cadence: "weekly", weekday: 0 }),
      ).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse(
        input(growth, { cadence: "weekly", weekday: 8 }),
      ).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse(
        input(growth, { cadence: "weekly", weekday: 7 }),
      ).success,
    ).toBe(true);
    expect(
      createRecurringIssueSchema.safeParse(input(growth, { title: "ab" })).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse(input(growth, { title: "a".repeat(181) }))
        .success,
    ).toBe(false);
  });
});

describe("service", () => {
  it("creates, lists in order, and pauses", async () => {
    const first = await recurringIssueService.createRecurringIssue(
      growth.actors.member,
      input(growth, { title: "First chore" }),
    );
    const second = await recurringIssueService.createRecurringIssue(
      growth.actors.member,
      input(growth, { title: "Second chore", cadence: "weekly", weekday: 3 }),
    );

    expect(first.lastOccurrenceOn).toBeNull();
    expect(first.paused).toBe(false);
    expect(first.createdBy).toBe(growth.actors.member.userId);
    expect(first.weekday).toBeNull();
    expect(second.weekday).toBe(3);

    const listed = await recurringIssueService.listRecurringIssues(
      growth.actors.viewer,
      growth.org.id,
    );
    expect(listed.map((rule) => rule.id)).toEqual([first.id, second.id]);

    const paused = await recurringIssueService.setRecurringIssuePaused(
      growth.actors.member,
      { orgId: growth.org.id, recurringIssueId: first.id, paused: true },
    );
    expect(paused.paused).toBe(true);
    expect(paused.lastOccurrenceOn).toBeNull();
  });

  it("rejects invalid input with ZodError and stores nothing", async () => {
    const before = await recurringIssueService.listRecurringIssues(
      free.actors.owner,
      free.org.id,
    );
    await expect(
      recurringIssueService.createRecurringIssue(
        free.actors.owner,
        input(free, { startsOn: "2026-02-30" }),
      ),
