  it("does not advance a rule when issue creation is refused, and still files the next rule", async () => {
    const quota = await createTenant("quota", "enterprise");
    const sibling = await createTenant("sibling", "enterprise");

    const blocked = await recurringIssueService.createRecurringIssue(
      quota.actors.member,
      input(quota, { title: "Over quota", startsOn: "2026-03-01" }),
    );
    const open = await recurringIssueService.createRecurringIssue(
      sibling.actors.member,
      input(sibling, { title: "Still filed", startsOn: "2026-03-01" }),
    );

    await getDb().$client
      .prepare("UPDATE organizations SET plan = 'free' WHERE id = ?")
      .run(quota.org.id);

    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quota.org.id, quota.project.id, { title: `Seed ${number}` }),
        quota.actors.member.userId,
        number,
      );
    }

    const result = await runRecurringIssueJob(new Date("2026-03-08T12:00:00.000Z"));
    expect(result.failed).toBeGreaterThanOrEqual(1);

    const blockedIssues = await titles(quota);
    expect(blockedIssues.some((title) => title.startsWith("Over quota"))).toBe(false);
    const stored = (
      await recurringIssueService.listRecurringIssues(quota.actors.owner, quota.org.id)
    ).find((row) => row.id === blocked.id);
    expect(stored?.paused).toBe(false);
    expect(stored?.lastOccurrenceOn).toBeNull();

    expect(await titles(sibling)).toContain("Still filed (2026-03-08)");
    const openStored = (
      await recurringIssueService.listRecurringIssues(
        sibling.actors.owner,
        sibling.org.id,
      )
    ).find((row) => row.id === open.id);
    expect(openStored?.lastOccurrenceOn).toBe("2026-03-08");
    expect(openStored?.paused).toBe(false);
  });

  it("runs when the queue drains a recurring-issues job", async () => {
    resetQueue();
    enqueue({
      id: "recurring-issues:manual",
      kind: "recurring-issues",
      runAt: toIsoTimestamp(new Date("2020-01-01T00:00:00.000Z")),
      attempts: 0,
      payload: {},
    });
    await expect(drain()).resolves.toBe(1);
    expect(pendingCount()).toBe(0);
  });
});

